SELECT IFNULL(MAX(amount), 0)
FROM wallet_histories
WHERE wallet_id = #{walletId}
  AND transaction_type = 'PAYMENT'
  AND status = 'SUCCESS'
  AND DATE_FORMAT(created_at, '%Y-%m') = #{yearMonth}

SELECT COUNT(DISTINCT DATE(created_at))
FROM wallet_histories
WHERE wallet_id = #{walletId}
  AND transaction_type = 'PAYMENT'
  AND status = 'SUCCESS'
  AND DATE_FORMAT(created_at, '%Y-%m') = #{yearMonth}

SELECT IFNULL(MAX(merchant_total), 0)
FROM (
         SELECT SUM(amount) AS merchant_total
         FROM wallet_histories
         WHERE wallet_id = #{walletId}
           AND transaction_type = 'PAYMENT'
           AND status = 'SUCCESS'
           AND DATE_FORMAT(created_at, '%Y-%m') = #{yearMonth}
         GROUP BY merchant_id
     ) merchant_totals

SELECT COUNT(*)
FROM piggy_banks
WHERE wallet_id = #{walletId}
  AND status = 'ACHIEVE'
  AND DATE_FORMAT(achieved_at, '%Y-%m') = #{yearMonth}
